fn find_workspace_root() -> Result<PathBuf> {
    let mut current = std::env::current_dir()?;
    loop {
        let cargo_toml = current.join("Cargo.toml");
        if cargo_toml.exists() {
            let content = std::fs::read_to_string(&cargo_toml)?;
            if content.contains("[workspace]") {
                return Ok(current);
            }
        }
        if !current.pop() {
            anyhow::bail!("Could not find workspace root (no Cargo.toml with [workspace] found)");
        }
    }
}

pub async fn timely_payments_scenario(
    sub: Subject,
    app: &LanaApp,
    clock: &ClockHandle,
    clock_ctrl: &ClockController,
) -> anyhow::Result<()> {
    event!(tracing::Level::INFO, "Starting timely payments scenario");

    let mut stream = app.outbox().listen_persisted(None);

    let (customer_id, _) = helpers::create_customer(&sub, app, "1-timely-paid").await?;
    let deposit_amount = UsdCents::try_from_usd(dec!(10_000_000))?;
    helpers::make_deposit(&sub, app, &customer_id, deposit_amount).await?;

    let cf_terms = helpers::std_terms();
    let cf_amount = UsdCents::try_from_usd(dec!(10_000_000))?;
    let custodian_id = helpers::get_or_create_manual_custodian(&sub, app).await?;
    let cf_proposal = app
        .create_facility_proposal(&sub, customer_id, cf_amount, cf_terms, custodian_id)
        .await?;
    let proposal_id = cf_proposal.id;
    let cf_id: CreditFacilityId = proposal_id.into();

    app.credit()
        .proposals()
        .conclude_customer_approval(&sub, proposal_id, true)
        .await?;

    let mut wait = MIN_EVENT_WAIT;
    loop {
        tokio::select! {
            Some(msg) = stream.next() => {
                wait = MIN_EVENT_WAIT;
                if let Some(LanaEvent::Credit(CoreCreditEvent::FacilityProposalConcluded {
                    entity,
                })) = &msg.payload
                    && entity.status == CreditFacilityProposalStatus::Approved
                    && entity.id == proposal_id
                {
                    msg.inject_trace_parent();
                    break;
                }
                if let Some(LanaEvent::Credit(CoreCreditEvent::FacilityProposalConcluded {
                    entity,
                })) = &msg.payload
                    && entity.status == CreditFacilityProposalStatus::Denied
                    && entity.id == proposal_id
                {
                    anyhow::bail!("Proposal was denied");
                }
            }
            _ = tokio::time::sleep(wait) => {
                clock_ctrl.advance(ONE_DAY).await;
                wait = (wait * 2).min(MAX_EVENT_WAIT);
            }
        }
    }

    let pending_facility = app
        .credit()
        .pending_credit_facilities()
        .find_by_id(&sub, proposal_id)
        .await?
        .expect("pending facility exists");

    app.credit()
        .collaterals()
        .update_collateral_by_id(
            &sub,
            pending_facility.collateral_id,
            Satoshis::try_from_btc(dec!(230))?,
            clock.today(),
        )
        .await?;

    let activation_date;
    let mut wait = MIN_EVENT_WAIT;
    loop {
        tokio::select! {
            Some(msg) = stream.next() => {
                wait = MIN_EVENT_WAIT;
                if let Some(LanaEvent::Credit(CoreCreditEvent::FacilityActivated { entity })) = &msg.payload
                    && entity.id == cf_id
                {
                    msg.inject_trace_parent();
                    activation_date = clock.today();
                    break;
                }
            }
            _ = tokio::time::sleep(wait) => {
                clock_ctrl.advance(ONE_DAY).await;
                wait = (wait * 2).min(MAX_EVENT_WAIT);
            }
        }
    }

    let expected_end_date = activation_date + chrono::Duration::days(95);

    let mut wait = MIN_EVENT_WAIT;
    loop {
        tokio::select! {
            Some(msg) = stream.next() => {
                wait = MIN_EVENT_WAIT;
                if let Some(LanaEvent::CreditCollection(CoreCreditCollectionEvent::ObligationDue {
                    entity,
                })) = &msg.payload
                    && CreditFacilityId::from(entity.beneficiary_id) == cf_id
                    && entity.outstanding_amount > UsdCents::ZERO
                {
                    msg.inject_trace_parent();
                    app.record_payment_with_date(&sub, cf_id, entity.outstanding_amount, clock.today()).await?;
                }
            }
            _ = tokio::time::sleep(wait) => {
                if clock.today() >= expected_end_date {
                    break;
                }
                clock_ctrl.advance(ONE_DAY).await;
                wait = (wait * 2).min(MAX_EVENT_WAIT);
            }
        }
    }

    loop {
        let facility = app
            .credit()
            .facilities()
            .find_by_id(&sub, cf_id)
            .await?
            .expect("facility exists");

        if facility.interest_accrual_cycle_in_progress().is_some() {
            tokio::time::sleep(MIN_EVENT_WAIT).await;
            clock_ctrl.advance(TEN_MINUTES).await;
            continue;
        }

        let total_outstanding = app.credit().outstanding(&facility).await?;
        if total_outstanding.is_zero() {
            break;
        }

        app.record_payment_with_date(&sub, cf_id, total_outstanding, clock.today())
            .await?;
        tokio::time::sleep(MIN_EVENT_WAIT).await;
    }

    let _facility = app.credit().complete_facility(&sub, cf_id).await?;

    event!(tracing::Level::INFO, facility_id = %cf_id, "Timely payments scenario completed");
    Ok(())
}

// impl CoreAccess
pub async fn init(
        pool: &sqlx::PgPool,
        config: AccessConfig,
        all_actions: Vec<ActionMapping>,
        predefined_roles: &'static [(&'static str, &'static [&'static str])],
        authz: &Authorization<Audit, AuthRoleToken>,
        outbox: &Outbox<E>,
        clock: ClockHandle,
    ) -> Result<Self, CoreAccessError> {
        let users = Users::init(pool, authz, outbox, clock.clone()).await?;
        let publisher = UserPublisher::new(outbox);
        let role_repo = RoleRepo::new(pool, &publisher, clock.clone());
        let permission_set_repo = PermissionSetRepo::new(pool, clock.clone());

        if let Some(email) = config.superuser_email {
            let bootstrap =
                bootstrap::Bootstrap::new(authz, &role_repo, &users, &permission_set_repo);
            bootstrap
                .bootstrap_access_control(email, all_actions, predefined_roles)
                .await?;
        }

        let core_access = Self {
            authz: authz.clone(),
            users,
            roles: role_repo,
            permission_sets: permission_set_repo,
        };

        Ok(core_access)
    }

