impl ErrorSeverity for CollectionLedgerError {
    fn severity(&self) -> Level {
        match self {
            Self::Sqlx(_) => Level::ERROR,
            Self::CalaLedger(_) => Level::ERROR,
            Self::CalaTxTemplate(_) => Level::ERROR,
            Self::CalaVelocity(cala_ledger::velocity::error::VelocityError::Enforcement(_)) => {
                Level::WARN
            }
            Self::CalaVelocity(_) => Level::ERROR,
            Self::PaymentAmountGreaterThanOutstandingObligations => Level::WARN,
        }
    }
}

impl TryFromEvents<ReportEvent> for Report {
    fn try_from_events(events: EntityEvents<ReportEvent>) -> Result<Self, EntityHydrationError> {
        let mut builder = ReportBuilder::default();

        for event in events.iter_all() {
            match event {
                ReportEvent::Initialized {
                    id,
                    external_id,
                    run_id,
                    name,
                    norm,
                    files,
                } => {
                    builder = builder
                        .id(*id)
                        .external_id(external_id.clone())
                        .run_id(*run_id)
                        .name(name.clone())
                        .norm(norm.clone())
                        .files(files.clone())
                }
            }
        }

        builder.events(events).build()
    }
}

