pub async fn start_poll(&mut self) -> Result<(), JobError> {
        let registry = self
            .registry
            .lock()
            .expect("Couldn't lock Registry Mutex")
            .take()
            .expect("Registry has been consumed by executor");
        self.poller_handle = Some(Arc::new(
            JobPoller::new(
                self.config.poller_config.clone(),
                Arc::clone(&self.repo),
                registry,
                self.clock.clone(),
            )
            .start()
            .await?,
        ));
        Ok(())
    }

