    E: OutboxEventMarker<CoreCreditCollectionEvent>,
{
    #[instrument(name = "core_credit.allocate_credit_facility_payment_job.process_message_in_op", parent = None, skip(self, op, event), fields(seq = %event.sequence, handled = false, event_type = tracing::field::Empty, credit_facility_id = tracing::field::Empty))]
    async fn handle_persistent(
        &self,
        op: &mut es_entity::DbOp<'_>,
        event: &PersistentOutboxEvent<E>,
    ) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        use CoreCreditCollectionEvent::*;

        if let Some(e @ PaymentCreated { entity }) = event.as_event() {
            event.inject_trace_parent();
            Span::current().record("handled", true);
            Span::current().record("event_type", e.as_ref());
            Span::current().record(
                "credit_facility_id",
                tracing::field::display(&entity.beneficiary_id),
            );

            self.allocate_payment
                .spawn_with_queue_id_in_op(
                    op,
                    JobId::new(),
                    AllocatePaymentConfig {
                        payment_id: entity.id,
                    },
                    entity.id.to_string(),
                )
                .await?;
        }
        Ok(())
    }
}

pub async fn create_active_facility(
    ctx: &TestContext,
    terms: TermValues,
) -> anyhow::Result<ActiveFacilityState> {
    let state = create_pending_facility(ctx, terms).await?;

    let collateral_satoshis = Satoshis::from(50_000_000); // 0.5 BTC
    let effective = chrono::Utc::now().date_naive();
    let facility_id: CreditFacilityId = state.pending_facility_id.into();

    let collaterals = ctx.credit.collaterals().clone();
    let collateral_id = state.collateral_id;

    event::expect_event(
        &ctx.outbox,
        move || {
            let collaterals = collaterals.clone();
            async move {
                collaterals
                    .update_collateral_by_id(
                        &DummySubject,
                        collateral_id,
                        collateral_satoshis,
                        effective,
                    )
                    .await
            }
        },
        |_result, e| match e {
            CoreCreditEvent::FacilityActivated { entity } if entity.id == facility_id => Some(()),
            _ => None,
        },
    )
    .await?;

    Ok(ActiveFacilityState {
        facility_id,
        collateral_id: state.collateral_id,
        deposit_account_id: state.deposit_account_id,
        customer_id: state.customer_id,
        amount: state.amount,
    })
}

