async fn setup_at(start: DateTime<Utc>) -> anyhow::Result<(TestSetup, ClockController)> {
    let pool = helpers::init_pool().await?;
    let (clock, clock_ctrl) = ClockHandle::artificial(ArtificialClockConfig::manual_at(start));

    let outbox = obix::Outbox::<event::DummyEvent>::init(
        &pool,
        obix::MailboxConfig::builder()
            .clock(clock.clone())
            .build()?,
    )
    .await?;

    let authz = authz::dummy::DummyPerms::<action::DummyAction, object::DummyObject>::new();
    let governance = governance::Governance::new(&pool, &authz, &outbox, clock.clone(), None);

    let cala_config = CalaLedgerConfig::builder()
        .pool(pool.clone())
        .exec_migrations(false)
        .clock(clock.clone())
        .build()?;
    let cala = CalaLedger::init(cala_config).await?;
    let mut jobs = job::Jobs::init(
        job::JobSvcConfig::builder()
            .pool(pool.clone())
            .clock(clock.clone())
            .build()
            .unwrap(),
    )
    .await?;

    let storage = Storage::new(&StorageConfig::default());
    let document_storage = DocumentStorage::new(&pool, &storage, clock.clone());
    let journal_id = helpers::init_journal(&cala).await?;
    let public_ids = public_id::PublicIds::new(&pool);

    let (internal_domain_configs, exposed_domain_configs, exposed_domain_configs_readonly) =
        helpers::init_domain_configs(&pool, &authz).await?;

    let customers = Customers::new(
        &pool,
        &authz,
        &outbox,
        document_storage,
        public_ids.clone(),
        &exposed_domain_configs_readonly,
        clock.clone(),
    );

    let deposit = CoreDeposit::init(
        &pool,
        &authz,
        &outbox,
        &governance,
        &mut jobs,
        &cala,
        journal_id,
        &public_ids,
        &customers,
        &exposed_domain_configs_readonly,
        &internal_domain_configs,
    )
    .await?;

    Ok((
        (deposit, customers, outbox, jobs, exposed_domain_configs),
        clock_ctrl,
    ))
}

// impl Test
pub async fn close_all_months_in_fiscal_year(&mut self) -> Result<()> {
        const MAX_MONTHS_IN_FISCAL_YEAR: usize = 12;
        let mut months_closed = 0;

        while !self.fiscal_year.is_last_month_of_year_closed() {
            if months_closed >= MAX_MONTHS_IN_FISCAL_YEAR {
                return Err(anyhow!("Max months in fiscal year reached"));
            }
            self.fiscal_year = self
                .accounting
                .fiscal_year()
                .close_month(&DummySubject, self.fiscal_year.id)
                .await?;

            months_closed += 1;
        }
        Ok(())
    }

