impl<S: std::fmt::Display> ClosingTransactionParams<S> {
    pub(super) fn new(
        journal_id: JournalId,
        description: String,
        effective: NaiveDate,
        entries_params: Vec<EntryParams>,
        initiated_by: S,
    ) -> ClosingTransactionParams<S> {
        Self {
            journal_id,
            description,
            effective,
            entries_params,
            initiated_by,
        }
    }

    pub(super) fn defs(n: usize) -> Vec<NewParamDefinition> {
        let mut params = vec![
            NewParamDefinition::builder()
                .name("journal_id")
                .r#type(ParamDataType::Uuid)
                .build()
                .unwrap(),
            NewParamDefinition::builder()
                .name("description")
                .r#type(ParamDataType::String)
                .build()
                .unwrap(),
            NewParamDefinition::builder()
                .name("effective")
                .r#type(ParamDataType::Date)
                .build()
                .unwrap(),
            NewParamDefinition::builder()
                .name("meta")
                .r#type(ParamDataType::Json)
                .build()
                .unwrap(),
        ];
        for i in 0..n {
            params.extend(EntryParams::defs_for_entry(i));
        }
        params
    }

    pub(super) fn template_code(&self) -> String {
        format!("CLOSING_TRANSACTION_{}", self.description)
    }

    pub(super) fn tx_entry_type(&self, i: usize) -> String {
        format!("'CLOSING_TRANSACTION_{}_ENTRY_{}'", self.description, i)
    }
}

impl Expression {
    pub(crate) fn from_op(op: LeftRightOp, left: Box<Expression>, right: Box<Expression>) -> Self {
        use LeftRightOp::*;
        match op {
            Logic(LogicOp::Or) => Expression::Ternary(
                left,
                Box::new(Expression::Literal(Literal::Bool(true))),
                right,
            ),
            Logic(LogicOp::And) => Expression::Ternary(
                left,
                right,
                Box::new(Expression::Literal(Literal::Bool(false))),
            ),
            Relation(op) => Expression::Relation(op, left, right),
            Arithmetic(op) => Expression::Arithmetic(op, left, right),
        }
    }
}

impl TryFrom<CelResult<'_>> for Currency {
    type Error = ResultCoercionError;

    fn try_from(CelResult { expr, val }: CelResult) -> Result<Self, Self::Error> {
        match val {
            CelValue::String(v) => v.as_ref().parse::<Currency>().map_err(|e| {
                ResultCoercionError::ExternalTypeCoercionError(
                    format!("{expr:?}"),
                    format!("{v:?}"),
                    "Currency",
                    format!("{e:?}"),
                )
            }),
            v => Err(ResultCoercionError::BadExternalTypeCoercion(
                format!("{expr:?}"),
                CelType::from(&v),
                "Currency",
            )),
        }
    }
}

impl From<TransactionFindError> for TransactionError {
    fn from(error: TransactionFindError) -> Self {
        match error {
            TransactionFindError::NotFound {
                column: Some(TransactionColumn::Id),
                value,
                ..
            } => Self::CouldNotFindById(value.parse().expect("invalid uuid")),
            TransactionFindError::NotFound {
                column: Some(TransactionColumn::ExternalId),
                value,
                ..
            } => Self::CouldNotFindByExternalId(value),
            other => Self::Find(other),
        }
    }
}

