// impl Governance
pub async fn init_policy(
        &self,
        process_type: ApprovalProcessType,
    ) -> Result<Policy, GovernanceError> {
        let mut db = self.policy_repo.begin_op().await?;
        let auto_approval_allowed = self.auto_approval_allowed_in_op(&mut db).await?;

        if let Some(existing) = self
            .policy_repo
            .maybe_find_by_process_type_in_op(&mut db, process_type.clone())
            .await?
        {
            return Ok(existing);
        }

        self.authz
            .audit()
            .record_system_entry_in_op(
                &mut db,
                audit::SystemActor::BOOTSTRAP,
                GovernanceObject::all_policies(),
                GovernanceAction::POLICY_CREATE,
            )
            .await?;

        let rules = if !auto_approval_allowed {
            let committee = self
                .committee_repo
                .maybe_find_by_name_in_op(&mut db, DEFAULT_COMMITTEE_NAME)
                .await?
                .ok_or(GovernanceError::DefaultCommitteeNotFound)?;
            Some(ApprovalRules::Committee {
                committee_id: committee.id,
            })
        } else {
            None
        };

        let new_policy = NewPolicy::try_new(
            PolicyId::new(),
            process_type.clone(),
            rules,
            auto_approval_allowed,
        )?;

        match self
            .policy_repo
            .create_in_op(&mut db, new_policy)
            .await
            .map_err(PolicyError::from)
        {
            Ok(policy) => {
                db.commit().await?;
                Ok(policy)
            }
            Err(PolicyError::DuplicateApprovalProcessType) => {
                let policy = self.policy_repo.find_by_process_type(process_type).await?;
                Ok(policy)
            }
            Err(e) => Err(e.into()),
        }
    }

