fn update_collateralization_ratio(
        &mut self,
        balance: &PendingCreditFacilityBalanceSummary,
    ) -> Idempotent<()> {
        let ratio = balance.current_collateralization_ratio();

        if self.last_collateralization_ratio() == ratio {
            return Idempotent::AlreadyApplied;
        }

        self.events
            .push(PendingCreditFacilityEvent::CollateralizationRatioChanged {
                collateralization_ratio: ratio,
            });
        Idempotent::Executed(())
    }

// impl SumsubClient
pub async fn simulate_review_response(
        &self,
        applicant_id: &str,
        review_answer: &str, // "GREEN" or "RED"
    ) -> Result<(), SumsubError> {
        let method = "POST";
        let url_path = format!("/resources/applicants/{applicant_id}/status/testCompleted");
        let full_url = self.base_url.join(&url_path).expect("valid URL");

        let body = if review_answer == wire::testing::REVIEW_ANSWER_GREEN {
            json!({
                "reviewAnswer": wire::testing::REVIEW_ANSWER_GREEN,
                "rejectLabels": []
            })
        } else {
            json!({
                "reviewAnswer": wire::testing::REVIEW_ANSWER_RED,
                "rejectLabels": ["UNSATISFACTORY_PHOTOS"],
                "reviewRejectType": "RETRY",
                "clientComment": "Test rejection for automated testing",
                "moderationComment": "This is a simulated rejection for testing purposes"
            })
        };

        let body_str = body.to_string();
        let headers = self.get_headers(method, &url_path, Some(&body_str))?;

        let response = self
            .client
            .post(full_url)
            .headers(headers)
            .body(body_str)
            .send()
            .await?;

        if response.status().is_success() {
            Ok(())
        } else {
            let response_text = response.text().await?;
            match serde_json::from_str::<wire::SumsubResponse<serde_json::Value>>(&response_text) {
                Ok(wire::SumsubResponse::Error(wire::ApiError { description, code })) => {
                    Err(SumsubError::ApiError { description, code })
                }
                _ => Err(SumsubError::InvalidResponse(format!(
                    "Failed to simulate review: {response_text}"
                ))),
            }
        }
    }

#[instrument(name = "cel.builtin.decimal.cast", skip_all, err, level = "debug")]
pub fn cast(args: Vec<CelValue>) -> Result<CelValue, CelError> {
    match args.first() {
        Some(CelValue::Decimal(d)) => Ok(CelValue::Decimal(*d)),
        Some(CelValue::String(s)) => Ok(CelValue::Decimal(
            s.parse()
                .map_err(|e| CelError::DecimalError(format!("{e:?}")))?,
        )),
        Some(v) => Err(CelError::BadType(CelType::Decimal, CelType::from(v))),
        None => Err(CelError::MissingArgument),
    }
}

#[instrument(name = "cel.builtin.decimal.add", skip_all, err, level = "debug")]
pub fn add(args: Vec<CelValue>) -> Result<CelValue, CelError> {
    let a: &Decimal = assert_arg(args.first())?;
    let b: &Decimal = assert_arg(args.get(1))?;
    Ok(CelValue::Decimal(a + b))
}

#[instrument(name = "cel.builtin.date", skip_all, level = "debug", err)]
pub(crate) fn date(ctx: &CelContext, args: Vec<CelValue>) -> Result<CelValue, CelError> {
    if args.is_empty() {
        return Ok(CelValue::Date(ctx.clock().now().date_naive()));
    }

    let s: Arc<String> = assert_arg(args.first())?;
    Ok(CelValue::Date(NaiveDate::parse_from_str(&s, "%Y-%m-%d")?))
}

#[instrument(name = "cel.builtin.uuid", skip_all, level = "debug", err)]
pub(crate) fn uuid(args: Vec<CelValue>) -> Result<CelValue, CelError> {
    let s: Arc<String> = assert_arg(args.first())?;
    Ok(CelValue::Uuid(
        s.parse()
            .map_err(|e| CelError::UuidError(format!("{e:?}")))?,
    ))
}

fn assert_arg<'a, T: TryFrom<&'a CelValue, Error = CelError>>(
    arg: Option<&'a CelValue>,
) -> Result<T, CelError> {
    if let Some(v) = arg {
        T::try_from(v)
    } else {
        Err(CelError::MissingArgument)
    }
}

