// impl ApprovalProcess
pub(crate) fn approve(
        &mut self,
        eligible_members: &HashSet<CommitteeMemberId>,
        approver_id: CommitteeMemberId,
    ) -> Idempotent<()> {
        use ApprovalProcessEvent::*;
        idempotency_guard!(
            self.events.iter_all(),
            already_applied: Concluded {..},
            already_applied: Approved {approver_id: id, ..} | Denied {denier_id: id,..} if id == &approver_id,
        );

        if !eligible_members.contains(&approver_id) {
            return Idempotent::AlreadyApplied;
        }

        self.events
            .push(ApprovalProcessEvent::Approved { approver_id });
        self.maybe_conclude(eligible_members);

        Idempotent::Executed(())
    }

// impl CreditFacility
fn maybe_initiate_partial_liquidation(
        &mut self,
        state: CollateralizationState,
        price: PriceOfOneBTC,
        balances: CreditFacilityBalanceSummary,
    ) -> Idempotent<()> {
        if !state.is_under_liquidation_threshold() {
            return Idempotent::AlreadyApplied;
        }

        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: CreditFacilityEvent::PartialLiquidationInitiated { .. },
            resets_on: CreditFacilityEvent::ProceedsFromPartialLiquidationApplied { .. }
        );

        if balances.total_outstanding().is_zero() {
            return Idempotent::AlreadyApplied;
        }

        let amount = balances.total_outstanding();

        let payment = LiquidationPaymentAmounts::calculate_liquidation_payment(
            amount,
            price,
            self.terms.initial_cvl,
            balances.collateral(),
        );

        self.events
            .push(CreditFacilityEvent::PartialLiquidationInitiated {
                liquidation_id: LiquidationId::new(),
                trigger_price: price,
                initially_expected_to_receive: payment.to_receive,
                initially_estimated_to_liquidate: payment.to_liquidate,
            });

        Idempotent::Executed(())
    }

// impl Prospect
pub fn close(&mut self) -> Result<Idempotent<()>, ProspectError> {
        idempotency_guard!(self.events.iter_all().rev(), already_applied: ProspectEvent::Closed { .. });
        self.ensure_open()?;
        self.stage = ProspectStage::Closed;
        let stage = self.stage;
        self.events.push(ProspectEvent::Closed { stage });
        self.stage = stage;
        Ok(Idempotent::Executed(()))
    }

// impl Collateral
pub fn record_proceeds_received_and_liquidation_completed(
        &mut self,
        amount_received: UsdCents,
    ) -> Result<Idempotent<RecordProceedsFromLiquidationData>, CollateralError> {
        let (liquidation_id, data) = {
            let liquidation = self
                .active_liquidation()
                .ok_or(CollateralError::NoActiveLiquidation)?;

            let ledger_tx_id = liquidation
                .record_proceeds_from_liquidation_and_complete(amount_received)
                .expect("Active liquidation in incorrect \"completed\" state");

            let data = RecordProceedsFromLiquidationData::new(
                liquidation.account_ids,
                amount_received,
                liquidation.sent_total,
                ledger_tx_id,
            );
            (liquidation.id, data)
        };

        self.events
            .push(CollateralEvent::LiquidationProceedsReceived {
                liquidation_id,
                amount: amount_received,
                ledger_tx_id: data.ledger_tx_id,
                payment_id: PaymentId::new(),
            });

        self.events
            .push(CollateralEvent::LiquidationCompleted { liquidation_id });

        Ok(Idempotent::Executed(data))
    }

