// impl Prospect
pub fn convert_manually(
        &mut self,
        allow_manual: bool,
    ) -> Result<Idempotent<NewCustomer>, ProspectError> {
        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: ProspectEvent::ManuallyConverted { .. }
        );
        if !allow_manual {
            return Err(ProspectError::ManualConversionNotAllowed);
        }
        self.ensure_open()?;
        self.kyc_status = KycStatus::Approved;
        let stage = self.compute_stage();
        self.events.push(ProspectEvent::ManuallyConverted { stage });
        self.stage = stage;

        let new_customer = NewCustomer::builder()
            .id(CustomerId::from(self.id))
            .party_id(self.party_id)
            .customer_type(self.customer_type)
            .public_id(self.public_id.clone())
            .conversion(CustomerConversion::ManuallyConverted)
            .level(KycLevel::Basic)
            .build()
            .expect("Could not build customer from prospect");

        Ok(Idempotent::Executed(new_customer))
    }

// impl Chart
pub(super) fn configure_with_initial_accounts(
        &mut self,
        account_specs: Vec<AccountSpec>,
        base_config: AccountingBaseConfig,
        journal_id: CalaJournalId,
    ) -> Result<Idempotent<BulkImportResult>, ChartOfAccountsError> {
        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: ChartEvent::BaseConfigSet { base_config: existing, .. } if &base_config == existing,
        );
        if self.base_config.is_some() {
            return Err(ChartOfAccountsError::BaseConfigAlreadyInitializedWithDifferentConfig);
        }

        let res = BulkAccountImport::new(self, journal_id).import(account_specs);

        self.check_base_config_codes_exists_in_chart(&base_config)?;
        self.events.push(ChartEvent::BaseConfigSet {
            base_config: base_config.clone(),
        });
        self.base_config = Some(base_config);

        Ok(Idempotent::Executed(res))
    }

