// impl DomainConfig
pub(super) fn update_value_encrypted<C>(
        &mut self,
        key: &EncryptionKey,
        new_value: <C::Kind as ValueKind>::Value,
    ) -> Result<Idempotent<()>, DomainConfigError>
    where
        C: ConfigSpec<Flavor = DomainConfigFlavorEncrypted>,
    {
