// impl Transaction
pub(super) fn void(
        &mut self,
        new_tx_id: TransactionId,
        entry_ids: Vec<EntryId>,
        created_at: chrono::DateTime<chrono::Utc>,
    ) -> Result<NewTransaction, TransactionError> {
        if self.is_voided() {
            return Err(TransactionError::AlreadyVoided(self.id));
        }

        self.values.voided_by = Some(new_tx_id);
        let fields = vec!["voided_by".to_string()];

        self.events.push(TransactionEvent::Updated {
            values: self.values.clone(),
            fields,
        });

        let values = self.values();

        let mut builder = NewTransaction::builder();
        builder
            .id(new_tx_id)
            .tx_template_id(values.tx_template_id)
            .void_of(values.id)
            .entry_ids(entry_ids.into_iter().collect())
            .effective(created_at.date_naive())
            .journal_id(values.journal_id)
            .correlation_id(values.correlation_id.clone())
            .created_at(created_at);

        if let Some(ref external_id) = values.external_id {
            builder.external_id(external_id);
        }
        if let Some(ref description) = values.description {
            builder.description(description);
        }
        if let Some(ref metadata) = values.metadata {
            builder.metadata(metadata.clone());
        }
        let new_transaction = builder.build().expect("Couldn't build voided transaction");
        Ok(new_transaction)
    }

// impl Collateral
pub fn record_collateral_update_via_custodian_sync(
        &mut self,
        new_amount: Satoshis,
        effective: chrono::NaiveDate,
    ) -> Idempotent<CollateralUpdate> {
        let current = self.amount;

        let (abs_diff, direction) = match new_amount.cmp(&current) {
            Ordering::Less => (current - new_amount, CollateralDirection::Remove),
            Ordering::Greater => (new_amount - current, CollateralDirection::Add),
            Ordering::Equal => return Idempotent::AlreadyApplied,
        };

        let tx_id = LedgerTxId::new();

        self.events.push(CollateralEvent::UpdatedViaCustodianSync {
            ledger_tx_id: tx_id,
            abs_diff,
            collateral_amount: new_amount,
            direction,
        });

        self.amount = new_amount;

        Idempotent::Executed(CollateralUpdate {
            tx_id,
            collateral_account_id: self.account_id(),
            abs_diff,
            direction,
            effective,
        })
    }

