// impl InterestAccrualCycle
pub(crate) fn record_accrual_cycle(
        &mut self,
        InterestAccrualCycleData {
            interest,
            tx_ref,
            tx_id,
            effective,
            ..
        }: InterestAccrualCycleData,
    ) -> Idempotent<Option<NewObligation>> {
        idempotency_guard!(
            self.events.iter_all(),
            already_applied: InterestAccrualCycleEvent::InterestAccrualsPosted { .. }
        );

        if interest.is_zero() {
            self.events
                .push(InterestAccrualCycleEvent::InterestAccrualsPosted {
                    ledger_tx_id: tx_id,
                    tx_ref: tx_ref.to_string(),
                    obligation_id: None,
                    total: interest,
                    effective,
                });

            return Idempotent::Executed(None);
        }

        let due_date = self.accrual_cycle_ends_at();
        let overdue_date = self
            .terms
            .obligation_overdue_duration_from_due
            .map(|d| d.end_date(due_date));
        let liquidation_date = self
            .terms
            .obligation_liquidation_duration_from_due
            .map(|d| d.end_date(due_date));
        let new_obligation = NewObligation::builder()
            .id(ObligationId::new())
            .beneficiary_id(self.credit_facility_id)
            .obligation_type(ObligationType::Interest)
            .reference(tx_ref.to_string())
            .amount(interest)
            .tx_id(tx_id)
            .receivable_account_ids(self.account_ids.into())
            .defaulted_account_id(self.account_ids.defaulted_account_id())
            .due_date(due_date)
            .overdue_date(overdue_date)
            .liquidation_date(liquidation_date)
            .effective(effective)
            .build()
            .expect("could not build new interest accrual cycle obligation");

        self.events
            .push(InterestAccrualCycleEvent::InterestAccrualsPosted {
                ledger_tx_id: tx_id,
                tx_ref: tx_ref.to_string(),
                obligation_id: Some(new_obligation.id()),
                total: interest,
                effective,
            });

        Idempotent::Executed(Some(new_obligation))
    }

// impl Collateral
pub fn record_collateral_update_via_manual_input(
        &mut self,
        new_amount: Satoshis,
        effective: chrono::NaiveDate,
    ) -> Result<Idempotent<CollateralUpdate>, CollateralError> {
        if self.custody_wallet_id.is_some() {
            return Err(CollateralError::ManualUpdateError);
        }

        let current = self.amount;

        let (abs_diff, direction) = match new_amount.cmp(&current) {
            Ordering::Less => (current - new_amount, CollateralDirection::Remove),
            Ordering::Greater => (new_amount - current, CollateralDirection::Add),
            Ordering::Equal => return Ok(Idempotent::AlreadyApplied),
        };

        let tx_id = LedgerTxId::new();

        self.events.push(CollateralEvent::UpdatedViaManualInput {
            ledger_tx_id: tx_id,
            abs_diff,
            collateral_amount: new_amount,
            direction,
        });

        self.amount = new_amount;

        Ok(Idempotent::Executed(CollateralUpdate {
            tx_id,
            collateral_account_id: self.account_id(),
            abs_diff,
            direction,
            effective,
        }))
    }

