// impl DomainConfig
pub(super) fn update_value_plain<C>(
        &mut self,
        new_value: <C::Kind as ValueKind>::Value,
    ) -> Result<Idempotent<()>, DomainConfigError>
    where
        C: ConfigSpec<Flavor = DomainConfigFlavorPlaintext>,
    {
        Self::assert_compatible::<C>(self)?;
        C::validate(&new_value)?;
        let encoded = <C::Kind as ValueKind>::encode(&new_value)?;
        self.store_value_plain(encoded)
    }

// impl Custodian
pub fn rotate_encryption_key(
        &mut self,
        new_key: &EncryptionKey,
        deprecated_key: &EncryptionKey,
    ) -> Result<Idempotent<()>, CustodianError> {
        if self.encrypted_custodian_config.matches_key(new_key) {
            return Ok(Idempotent::AlreadyApplied);
        }

        let encrypted_config = CustodianConfig::rotate_encryption_key(
            new_key,
            deprecated_key,
            &self.encrypted_custodian_config,
        )?;

        self.encrypted_custodian_config = encrypted_config.clone();
        self.events.push(CustodianEvent::ConfigUpdated {
            encrypted_custodian_config: encrypted_config,
        });

        Ok(Idempotent::Executed(()))
    }

// impl DomainConfig
pub(super) fn apply_update_from_json(
        &mut self,
        entry: &crate::registry::ConfigSpecEntry,
        config: &crate::EncryptionConfig,
        new_value: serde_json::Value,
    ) -> Result<Idempotent<()>, DomainConfigError> {
        self.validate_update(entry, &new_value)?;
        if self.encrypted {
            self.store_value_encrypted(&config.encryption_key, new_value)
        } else {
            self.store_value_plain(new_value)
        }
    }

// impl Obligation
pub(crate) fn allocate_payment(
        &mut self,
        amount: UsdCents,
        PaymentDetailsForAllocation {
            payment_id,
            facility_payment_holding_account_id: payment_holding_account_id,
            effective,
            ..
        }: PaymentDetailsForAllocation,
    ) -> Idempotent<NewPaymentAllocation> {
        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: ObligationEvent::PaymentAllocated {payment_id: id, .. }  if *id == payment_id
        );
        let pre_payment_outstanding = self.outstanding();
        if pre_payment_outstanding.is_zero() {
            return Idempotent::AlreadyApplied;
        }

        let payment_amount = std::cmp::min(pre_payment_outstanding, amount);
        let allocation_id = PaymentAllocationId::new();
        self.events.push(ObligationEvent::PaymentAllocated {
            ledger_tx_id: allocation_id.into(),
            payment_id,
            payment_allocation_id: allocation_id,
            payment_allocation_amount: payment_amount,
        });

        let payment_allocation_idx = self
            .events()
            .iter_all()
            .filter(|e| matches!(e, ObligationEvent::PaymentAllocated { .. }))
            .count();
        let allocation = NewPaymentAllocation::builder()
            .id(allocation_id)
            .payment_id(payment_id)
            .beneficiary_id(self.beneficiary_id)
            .obligation_id(self.id)
            .payment_allocation_idx(payment_allocation_idx)
            .obligation_type(self.obligation_type)
            .receivable_account_id(
                self.receivable_account_id()
                    .expect("Obligation was already paid"),
            )
            .payment_holding_account_id(payment_holding_account_id)
            .effective(effective)
            .amount(payment_amount)
            .build()
            .expect("could not build new payment allocation");

        if self.outstanding().is_zero() {
            self.events.push(ObligationEvent::Completed { effective });
        }

        Idempotent::Executed(allocation)
    }

// impl Disbursal
fn settle_disbursal(
        &mut self,
        tx_id: LedgerTxId,
        tx_ref: &str,
        effective: chrono::NaiveDate,
    ) -> Idempotent<NewObligation> {
        idempotency_guard!(self.events.iter_all(), already_applied: DisbursalEvent::Settled { .. });
        let obligation_id = ObligationId::new();
        self.events.push(DisbursalEvent::Settled {
            ledger_tx_id: tx_id,
            obligation_id,
            amount: self.amount,
            effective,
        });

        Idempotent::Executed(
            NewObligation::builder()
                .id(obligation_id)
                .beneficiary_id(self.facility_id)
                .obligation_type(ObligationType::Disbursal)
                .reference(tx_ref.to_string())
                .amount(self.amount)
                .tx_id(tx_id)
                .receivable_account_ids(self.account_ids.into())
                .defaulted_account_id(self.account_ids.defaulted_account_id())
                .due_date(self.due_date)
                .overdue_date(self.overdue_date)
                .liquidation_date(self.liquidation_date)
                .effective(effective)
                .build()
                .expect("could not build new disbursal obligation"),
        )
    }

// impl Withdrawal
pub fn revert(&mut self) -> Result<Idempotent<WithdrawalReversalData>, WithdrawalError> {
        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: WithdrawalEvent::Reverted { .. }
        );

        if self.is_cancelled() {
            return Err(WithdrawalError::AlreadyCancelled(self.id));
        }

        if !self.is_confirmed() {
            return Err(WithdrawalError::NotConfirmed(self.id));
        }

        let ledger_tx_id = CalaTransactionId::new();

        self.events.push(WithdrawalEvent::Reverted {
            ledger_tx_id,
            status: WithdrawalStatus::Reverted,
        });

        Ok(Idempotent::Executed(WithdrawalReversalData {
            entity_id: self.id,
            ledger_tx_id,
            amount: self.amount,
            credit_account_id: self.deposit_account_id,
            correlation_id: self.id.to_string(),
            external_id: format!("lana:withdraw:{}:reverted", self.id),
        }))
    }

// impl Prospect
pub fn decline_kyc(&mut self, applicant_id: &str) -> Result<Idempotent<()>, ProspectError> {
        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: ProspectEvent::KycDeclined { .. },
            resets_on: ProspectEvent::KycApproved { .. }
        );
        self.ensure_open()?;
        let stored_id = self
            .applicant_id
            .as_deref()
            .ok_or(ProspectError::KycNotStarted)?;
        if stored_id != applicant_id {
            return Err(ProspectError::ApplicantIdMismatch {
                expected: self.applicant_id.clone(),
                actual: applicant_id.to_string(),
            });
        }
        self.kyc_status = KycStatus::Declined;
        let stage = self.compute_stage();
        self.events.push(ProspectEvent::KycDeclined { stage });
        self.stage = stage;
        Ok(Idempotent::Executed(()))
    }

