// impl CreditFacilityProposal
pub(super) fn conclude_approval_process(
        &mut self,
        approved: bool,
    ) -> Result<
        Idempotent<Option<(NewPendingCreditFacility, CustodianId)>>,
        CreditFacilityProposalError,
    > {
        idempotency_guard!(
            self.events.iter_all(),
            already_applied: CreditFacilityProposalEvent::ApprovalProcessConcluded { .. }
        );

        if !self.events.iter_all().rev().any(|event| {
            matches!(
                event,
                CreditFacilityProposalEvent::ApprovalProcessStarted { .. }
            )
        }) {
            return Err(CreditFacilityProposalError::ApprovalProcessNotStarted);
        }

        let approval_process_id = self
            .approval_process_id
            .expect("approval process id not set");

        let status = if approved {
            CreditFacilityProposalStatus::Approved
        } else {
            CreditFacilityProposalStatus::Denied
        };

        self.events
            .push(CreditFacilityProposalEvent::ApprovalProcessConcluded {
                approval_process_id,
                status,
            });
        if approved {
            let new_pending_facility = NewPendingCreditFacilityBuilder::default()
                .id(self.id)
                .credit_facility_proposal_id(self.id)
                .customer_id(self.customer_id)
                .customer_type(self.customer_type)
                .approval_process_id(approval_process_id)
                .ledger_tx_id(LedgerTxId::new())
                .account_ids(crate::PendingCreditFacilityAccountIds::new())
                .disbursal_credit_account_id(self.disbursal_credit_account_id)
                .collateral_id(CollateralId::new())
                .terms(self.terms)
                .amount(self.amount)
                .build()
                .expect("Could not build new pending credit facility");

            return Ok(Idempotent::Executed(Some((
                new_pending_facility,
                self.custodian_id,
            ))));
        }

        Ok(Idempotent::Executed(None))
    }

// impl Chart
pub(super) fn create_child_node(
        &mut self,
        parent_code: AccountCode,
        code: AccountCode,
        name: AccountName,
        journal_id: CalaJournalId,
    ) -> Result<Idempotent<NewChartAccountDetails>, ChartOfAccountsError> {
        let parent_normal_balance_type = self
            .find_node_details_by_code(&parent_code)
            .map(|details| details.spec.normal_balance_type)
            .ok_or(ChartOfAccountsError::ParentAccountNotFound(
                parent_code.to_string(),
            ))?;

        let spec = AccountSpec::try_new(
            Some(parent_code),
            code.into(),
            name,
            parent_normal_balance_type,
        )?;

        Ok(self.create_node_without_verifying_parent(&spec, journal_id))
    }

