// impl Chart
fn create_node_without_verifying_parent(
        &mut self,
        spec: &AccountSpec,
        journal_id: CalaJournalId,
    ) -> Idempotent<NewChartAccountDetails> {
        if self.find_node_details_by_code(&spec.code).is_some() {
            return Idempotent::AlreadyApplied;
        }

        let node_id = ChartNodeId::new();
        let ledger_account_set_id = CalaAccountSetId::new();

        let chart_node = NewChartNode {
            id: node_id,
            chart_id: self.id,
            spec: spec.clone(),
            ledger_account_set_id,
            children_node_ids: vec![],
        };

        let parent_account_set_id = spec
            .parent
            .as_ref()
            .and_then(|parent_code| {
                self.chart_nodes
                    .find_persisted_mut(|node| node.spec.code == *parent_code)
            })
            .map(|parent_node| {
                let _ = parent_node.add_child_node(chart_node.id);
                parent_node.account_set_id
            })
            .unwrap_or(self.account_set_id);

        let new_account_set = chart_node.new_account_set(journal_id);
        self.chart_nodes.add_new(chart_node);

        Idempotent::Executed(NewChartAccountDetails {
            new_account_set,
            parent_account_set_id,
        })
    }

// impl Custodian
pub fn update_custodian_config(
        &mut self,
        key: &EncryptionKey,
        new_config: CustodianConfig,
    ) -> Result<Idempotent<()>, CustodianError> {
        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: CustodianEvent::ConfigUpdated { encrypted_custodian_config }
                if encrypted_custodian_config.matches_key(key)
                    && key.decrypt_json::<CustodianConfig>(encrypted_custodian_config).ok().as_ref() == Some(&new_config),
            resets_on: CustodianEvent::ConfigUpdated { .. }
        );

        if !self.encrypted_custodian_config.matches_key(key) {
            return Err(CustodianError::StaleEncryptionKey);
        }

        let encrypted = new_config.encrypt(key);
        self.encrypted_custodian_config = encrypted.clone();

        self.events.push(CustodianEvent::ConfigUpdated {
            encrypted_custodian_config: encrypted,
        });

        Ok(Idempotent::Executed(()))
    }

// impl Disbursal
pub(crate) fn approval_process_concluded(
        &mut self,
        approved: bool,
        effective: chrono::NaiveDate,
    ) -> Idempotent<Option<NewObligation>> {
        idempotency_guard!(
            self.events.iter_all(),
            already_applied: DisbursalEvent::ApprovalProcessConcluded { .. }
        );
        self.events.push(DisbursalEvent::ApprovalProcessConcluded {
            approval_process_id: self.approval_process_id,
            approved,
        });
        let tx_id = LedgerTxId::new();
        let tx_ref: &str = &format!("disbursal-{}", self.id);
        let new_obligation = if approved {
            if let Idempotent::Executed(new_obligation) =
                self.settle_disbursal(tx_id, tx_ref, effective)
            {
                Some(new_obligation)
            } else {
                return Idempotent::AlreadyApplied;
            }
        } else {
            self.events.push(DisbursalEvent::Cancelled {
                ledger_tx_id: tx_id,
            });
            None
        };
        self.concluded_tx_id = Some(tx_id);

        Idempotent::Executed(new_obligation)
    }

// impl Job
pub(super) fn abort_execution(
        &mut self,
        reason: String,
        scheduled_at: DateTime<Utc>,
        attempt: u32,
    ) {
        self.events.push(JobEvent::ExecutionAborted { reason });
        self.events.push(JobEvent::ExecutionScheduled {
            attempt,
