// impl Withdrawal
pub fn confirm(&mut self) -> Result<Idempotent<CalaTransactionId>, WithdrawalError> {
        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: WithdrawalEvent::Confirmed { .. }
        );

        match self.is_approved_or_denied() {
            Some(false) => return Err(WithdrawalError::NotApproved(self.id)),
            None => return Err(WithdrawalError::NotApproved(self.id)),
            _ => (),
        }

        if self.is_cancelled() {
            return Err(WithdrawalError::AlreadyCancelled(self.id));
        }

        let ledger_tx_id = CalaTransactionId::new();
        self.events.push(WithdrawalEvent::Confirmed {
            ledger_tx_id,
            status: WithdrawalStatus::Confirmed,
        });

        Ok(Idempotent::Executed(ledger_tx_id))
    }

// impl Disbursal
pub(crate) fn approval_process_concluded_for_initial_disbursal(
        &mut self,
        effective: chrono::NaiveDate,
    ) -> Idempotent<Option<NewObligation>> {
        idempotency_guard!(
            self.events.iter_all(),
            already_applied: DisbursalEvent::ApprovalProcessConcluded { .. }
        );
        self.events.push(DisbursalEvent::ApprovalProcessConcluded {
            approval_process_id: self.approval_process_id,
            approved: true,
        });
        let tx_id = self.initiated_tx_id;
        let tx_ref: &str = &format!("initial-disbursal-{}", self.id);
        let new_obligation = if let Idempotent::Executed(new_obligation) =
            self.settle_disbursal(tx_id, tx_ref, effective)
        {
            Some(new_obligation)
        } else {
            return Idempotent::AlreadyApplied;
        };

        self.concluded_tx_id = Some(tx_id);

        Idempotent::Executed(new_obligation)
    }

