// impl PendingCreditFacility
pub(super) fn complete(
        &mut self,
        balances: PendingCreditFacilityBalanceSummary,
        price: PriceOfOneBTC,
        time: DateTime<Utc>,
    ) -> Result<Idempotent<NewCreditFacilityWithInitialDisbursal>, PendingCreditFacilityError> {
        idempotency_guard!(
            self.events.iter_all(),
            already_applied: PendingCreditFacilityEvent::Completed { .. }
        );

        let cvl = balances.current_cvl(price);
        if !self.terms.is_proposal_completion_allowed(cvl) {
            return Err(PendingCreditFacilityError::BelowMarginLimit);
        }

        self.events.push(PendingCreditFacilityEvent::Completed {});

        let mut new_credit_facility = NewCreditFacilityBuilder::default();
        let maturity_date = self.terms.maturity_date(time);
        let account_ids = crate::CreditFacilityLedgerAccountIds::from(self.account_ids);

        let collateralization_state = self.terms.collateralization(cvl);

        new_credit_facility
            .id(self.id)
            .pending_credit_facility_id(self.id)
            .ledger_tx_id(LedgerTxId::new())
            .customer_id(self.customer_id)
            .customer_type(self.customer_type)
            .account_ids(account_ids)
            .disbursal_credit_account_id(self.disbursal_credit_account_id)
            .collateral_id(self.collateral_id)
            .terms(self.terms)
            .amount(self.amount)
            .activated_at(time)
            .maturity_date(maturity_date)
            .collateralization_state(collateralization_state)
            .collateral(balances.collateral())
            .outstanding(CreditFacilityReceivable {
                disbursed: if self.is_single_disbursal() {
                    self.amount
                } else {
                    UsdCents::ZERO
                },
                interest: UsdCents::ZERO,
            })
            .price(price);

        let initial_disbursal = if self.is_single_disbursal() || !self.structuring_fee().is_zero() {
            let due_date = maturity_date;
            let overdue_date = self.terms.get_overdue_date_from_due_date(due_date);
            let liquidation_date = self.terms.get_liquidation_date_from_due_date(due_date);
            let disbursal_amount = if self.is_single_disbursal() {
                self.amount
            } else {
                self.structuring_fee()
            };

            let mut new_disbursal_builder = NewDisbursalBuilder::default();
            new_disbursal_builder
                .id(DisbursalId::new())
                .credit_facility_id(self.id)
                .approval_process_id(self.approval_process_id)
                .amount(disbursal_amount)
                .account_ids(account_ids.into())
                .disbursal_credit_account_id(self.disbursal_credit_account_id)
                .due_date(due_date)
                .overdue_date(overdue_date)
                .liquidation_date(liquidation_date);

            Some(new_disbursal_builder)
        } else {
            None
        };

        Ok(Idempotent::Executed(
            NewCreditFacilityWithInitialDisbursal {
                new_credit_facility,
                initial_disbursal,
            },
        ))
    }

// impl Chart
pub(super) fn create_node_with_existing_children(
        &mut self,
        spec: &AccountSpec,
        journal_id: CalaJournalId,
        children_node_ids: Vec<ChartNodeId>,
    ) -> Idempotent<NewAccountSetWithNodeId> {
        if self.find_node_details_by_code(&spec.code).is_some() {
            return Idempotent::AlreadyApplied;
        }

        let new_node_id = ChartNodeId::new();
        let chart_node = NewChartNode::builder()
            .id(new_node_id)
            .chart_id(self.id)
            .spec(spec.clone())
            .ledger_account_set_id(CalaAccountSetId::new())
            .children_node_ids(children_node_ids)
            .build()
            .expect("could not build NewChartNode");

        let new_account_set = chart_node.new_account_set(journal_id);
        self.chart_nodes.add_new(chart_node);

        Idempotent::Executed(NewAccountSetWithNodeId {
            new_account_set,
            node_id: new_node_id,
        })
    }

// impl Collateral
pub fn record_collateral_update_via_liquidation(
        &mut self,
        amount_sent: Satoshis,
        effective: chrono::NaiveDate,
    ) -> Result<Idempotent<CollateralUpdate>, CollateralError> {
        if amount_sent == Satoshis::ZERO {
            return Ok(Idempotent::AlreadyApplied);
        }

        let new_amount = self.amount - amount_sent;

        let (liquidation_id, tx_id) = {
            let liquidation = self
                .active_liquidation()
                .ok_or(CollateralError::NoActiveLiquidation)?;

            let tx_id = if let Idempotent::Executed(tx_id) =
                liquidation.record_collateral_sent_out(amount_sent)
            {
                tx_id
            } else {
                return Ok(Idempotent::AlreadyApplied);
            };

            (liquidation.id, tx_id)
        };

        self.events.push(CollateralEvent::UpdatedViaLiquidation {
            liquidation_id,
            abs_diff: amount_sent,
            collateral_amount: new_amount,
            ledger_tx_id: tx_id,
            direction: CollateralDirection::Remove,
        });
        self.amount = new_amount;

        Ok(Idempotent::Executed(CollateralUpdate {
            tx_id,
            collateral_account_id: self.account_id(),
            abs_diff: amount_sent,
            direction: CollateralDirection::Remove,
            effective,
        }))
    }

// impl Chart
pub(super) fn post_closing_tx_as_of(
        &mut self,
        account_codes: ClosingAccountCodes,
        tx_details: ClosingTxDetails,
    ) -> Result<Idempotent<ClosingTxParentIdsAndDetails>, ChartOfAccountsError> {
        let closing_tx_params = ClosingTxParentIdsAndDetails::new(
            self.closing_account_set_ids_from_codes(account_codes)?,
            tx_details,
        );
        let posted_as_of = closing_tx_params.posted_as_of();

        idempotency_guard!(
            self.events.iter_all().rev(),
            already_applied: ChartEvent::ClosingTransactionPosted { posted_as_of: prev_date, .. } if prev_date >= &posted_as_of,
            resets_on: ChartEvent::ClosingTransactionPosted { .. }
        );

        self.events
            .push(ChartEvent::ClosingTransactionPosted { posted_as_of });

        Ok(Idempotent::Executed(closing_tx_params))
    }

