#[tokio::test]
#[file_serial]
async fn superuser_permissions() -> anyhow::Result<()> {
    let pool = helpers::init_pool().await?;
    let audit = Audit::new(&pool);
    let authz = Authorization::init(&pool, &audit).await?;
    let (_, superuser_subject) = helpers::init_access(&pool, &authz).await?;

    // Superuser can create users
    assert!(
        authz
            .enforce_permission(
                &superuser_subject,
                CoreAccessObject::all_users(),
                CoreAccessAction::USER_CREATE,
            )
            .await
            .is_ok()
    );

    // Superuser can assign Admin role
    assert!(
        authz
            .enforce_permission(
                &superuser_subject,
                CoreAccessObject::all_users(),
                CoreAccessAction::USER_UPDATE_ROLE,
            )
            .await
            .is_ok()
    );

    // Superuser can assign Bank Manager role
    assert!(
        authz
            .enforce_permission(
                &superuser_subject,
                CoreAccessObject::user(UserId::new()),
                CoreAccessAction::USER_UPDATE_ROLE,
            )
            .await
            .is_ok()
    );

    Ok(())
}

#[macro_export]
macro_rules! map_action {
    ($module:ident, $discriminant:expr, $action_type:ty) => {{
        // Normalize identifier-style module names to kebab-case for action strings.
        const MODULE_NAME: &'static str = stringify!($module);
        let module_str = MODULE_NAME.replace('_', "-");

        let entity_str = $discriminant.to_string();
        <$action_type as strum::VariantArray>::VARIANTS
            .iter()
            .map(|variant| {
                ActionMapping::new(&module_str, &entity_str, variant, variant.permission_set())
            })
            .collect::<Vec<ActionMapping>>()
    }};
}

