impl RepaymentPlanRepo {
    pub fn new(pool: &PgPool) -> Self {
        Self { pool: pool.clone() }
    }

    pub async fn begin(
        &self,
    ) -> Result<sqlx::Transaction<'_, sqlx::Postgres>, CreditFacilityRepaymentPlanError> {
        Ok(self.pool.begin().await?)
    }

    #[record_error_severity]
    #[tracing::instrument(name = "repayment_plan.persist_in_tx", skip_all)]
    pub async fn persist_in_tx(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        credit_facility_id: CreditFacilityId,
        repayment_plan: CreditFacilityRepaymentPlan,
    ) -> Result<(), CreditFacilityRepaymentPlanError> {
        let json = serde_json::to_value(repayment_plan).expect("Could not serialize dashboard");
        let credit_facility_id: Uuid = credit_facility_id.into();
        sqlx::query!(
            r#"
            INSERT INTO core_credit_facility_repayment_plans (id, repayment_plan)
            VALUES ($1, $2)
            ON CONFLICT (id) DO UPDATE SET repayment_plan = $2
            "#,
            credit_facility_id,
            json
        )
        .execute(&mut **tx)
        .await?;
        Ok(())
    }

    #[record_error_severity]
    #[tracing::instrument(name = "repayment_plan.load", skip_all)]
    pub async fn load(
        &self,
        credit_facility_id: CreditFacilityId,
    ) -> Result<CreditFacilityRepaymentPlan, CreditFacilityRepaymentPlanError> {
        let credit_facility_id: Uuid = credit_facility_id.into();

        let row = sqlx::query!(
            "SELECT repayment_plan FROM core_credit_facility_repayment_plans WHERE id = $1",
            credit_facility_id
        )
        .fetch_optional(&self.pool)
        .await?;

        let repayment_plan = if let Some(row) = row {
            serde_json::from_value(row.repayment_plan).expect("valid json")
        } else {
            CreditFacilityRepaymentPlan::default()
        };

        Ok(repayment_plan)
    }
}

// impl BalanceRepo
pub(crate) async fn insert_new_snapshots(
        &self,
        op: &mut impl es_entity::AtomicOperation,
        journal_id: JournalId,
        new_balances: Vec<BalanceSnapshot>,
    ) -> Result<(), BalanceError> {
        tracing::Span::current().record(
            "n_new_balances",
            tracing::field::display(new_balances.len()),
        );

        let mut journal_ids = Vec::with_capacity(new_balances.len());
        let mut account_ids = Vec::with_capacity(new_balances.len());
        let mut entry_ids = Vec::with_capacity(new_balances.len());
        let mut currencies = Vec::with_capacity(new_balances.len());
        let mut versions = Vec::with_capacity(new_balances.len());
        let mut values = Vec::with_capacity(new_balances.len());

        for balance in new_balances.iter() {
            journal_ids.push(balance.journal_id);
            account_ids.push(balance.account_id);
            entry_ids.push(balance.entry_id);
            currencies.push(balance.currency.code());
            versions.push(balance.version as i32);
            values
                .push(serde_json::to_value(balance).expect("Failed to serialize balance snapshot"));
        }

        sqlx::query!(
            r#"
        WITH new_snapshots AS (
            INSERT INTO cala_balance_history (
                journal_id, account_id, currency, version, latest_entry_id, values
            )
            SELECT * FROM UNNEST (
                $1::uuid[],
                $2::uuid[],
                $3::text[],
                $4::int4[],
                $5::uuid[],
                $6::jsonb[]
            )
            RETURNING *
        )
        INSERT INTO cala_current_balances AS c (
            journal_id, account_id, currency, latest_version, latest_values
        )
        SELECT
            journal_id,
            account_id,
            currency,
            MAX(version) as latest_version,
            (array_agg(values ORDER BY version DESC))[1] as latest_values
        FROM new_snapshots
        GROUP BY journal_id, account_id, currency
        ON CONFLICT (account_id, journal_id, currency)
        DO UPDATE SET
            latest_version = GREATEST(c.latest_version, EXCLUDED.latest_version),
            latest_values = CASE
                WHEN c.latest_version < EXCLUDED.latest_version
                THEN EXCLUDED.latest_values
                ELSE c.latest_values
            END
        "#,
            &journal_ids as &[JournalId],
            &account_ids as &[AccountId],
            &currencies as &[&str],
            &versions as &[i32],
            &entry_ids as &[EntryId],
            &values
        )
        .execute(op.as_executor())
        .await?;

        self.publisher
            .publish_all(
                op,
                new_balances.into_iter().map(|balance| {
                    if balance.version == 1 {
                        OutboxEventPayload::BalanceCreated { balance }
                    } else {
                        OutboxEventPayload::BalanceUpdated { balance }
                    }
                }),
            )
            .await?;

        Ok(())
    }

