// impl VelocityBalanceRepo
pub async fn find_for_update(
        &self,
        op: &mut impl es_entity::AtomicOperation,
        keys: impl Iterator<Item = &VelocityBalanceKey>,
    ) -> Result<HashMap<VelocityBalanceKey, Option<BalanceSnapshot>>, VelocityError> {
        let mut sorted_keys: Vec<_> = keys.collect();
        sorted_keys.sort_by(|a, b| {
            a.account_id
                .cmp(&b.account_id)
                .then_with(|| a.control_id.cmp(&b.control_id))
                .then_with(|| a.limit_id.cmp(&b.limit_id))
                .then_with(|| a.currency.cmp(&b.currency))
                .then_with(|| a.journal_id.cmp(&b.journal_id))
        });

        let (windows, currencies, journal_ids, account_ids, control_ids, limit_ids) =
            sorted_keys.into_iter().fold(
                (
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                    Vec::new(),
                ),
                |(
                    mut windows,
                    mut currencies,
                    mut journal_ids,
                    mut account_ids,
                    mut control_ids,
                    mut limit_ids,
                ),
                 &VelocityBalanceKey {
                     ref window,
                     ref currency,
                     account_id,
                     journal_id,
                     control_id,
                     limit_id,
                 }| {
                    windows.push(window.inner().clone());
                    currencies.push(currency.code());
                    journal_ids.push(journal_id);
                    account_ids.push(account_id);
                    control_ids.push(control_id);
                    limit_ids.push(limit_id);
                    (
                        windows,
                        currencies,
                        journal_ids,
                        account_ids,
                        control_ids,
                        limit_ids,
                    )
                },
            );

        sqlx::query!(
            r#"
        SELECT pg_advisory_xact_lock(hashtext(concat(
            currency,
            journal_id::text,
            account_id::text,
            velocity_control_id::text,
            velocity_limit_id::text
        )))
        FROM UNNEST(
            $1::text[],
            $2::uuid[],
            $3::uuid[],
            $4::uuid[],
            $5::uuid[]
        )
        AS v(currency, journal_id, account_id, velocity_control_id, velocity_limit_id)
        ORDER BY account_id, velocity_control_id, velocity_limit_id, currency, journal_id
        "#,
            &currencies as &[&str],
            &journal_ids as &[JournalId],
            &account_ids as &[AccountId],
            &control_ids as &[VelocityControlId],
            &limit_ids as &[VelocityLimitId],
        )
        .execute(op.as_executor())
        .await?;

        let rows = sqlx::query!(
        r#"
        SELECT
            i.partition_window as "partition_window!: serde_json::Value",
            i.currency as "currency!",
            i.journal_id as "journal_id!: JournalId",
            i.account_id as "account_id!: AccountId",
            i.velocity_control_id as "velocity_control_id!: VelocityControlId",
            i.velocity_limit_id as "velocity_limit_id!: VelocityLimitId",
            b.latest_values as "values?: serde_json::Value"
        FROM UNNEST(
          $1::jsonb[],
          $2::text[],
          $3::uuid[],
          $4::uuid[],
          $5::uuid[],
          $6::uuid[]
        )
        AS i(partition_window, currency, journal_id, account_id, velocity_control_id, velocity_limit_id)
        LEFT JOIN cala_velocity_current_balances b
          ON i.partition_window = b.partition_window
          AND i.currency = b.currency
          AND i.journal_id = b.journal_id
          AND i.account_id = b.account_id
          AND i.velocity_control_id = b.velocity_control_id
          AND i.velocity_limit_id = b.velocity_limit_id
         "#,
           &windows[..],
           &currencies as &[&str],
           &journal_ids  as &[JournalId],
           &account_ids as &[AccountId],
           &control_ids  as &[VelocityControlId],
           &limit_ids  as &[VelocityLimitId],
        )
        .fetch_all(op.as_executor())
        .await?;

        let mut ret = HashMap::new();
        for row in rows {
            let snapshot = row.values.map(|v| {
                serde_json::from_value::<BalanceSnapshot>(v)
                    .expect("Failed to deserialize balance snapshot")
            });
            ret.insert(
                VelocityBalanceKey {
                    window: Window::from(row.partition_window),
                    currency: row.currency.parse().expect("Could not parse currency"),
                    journal_id: row.journal_id,
                    account_id: row.account_id,
                    control_id: row.velocity_control_id,
                    limit_id: row.velocity_limit_id,
                },
                snapshot,
            );
        }
        Ok(ret)
    }

