impl FromStr for CoreCreditCollectionAction {
    type Err = strum::ParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut elems = s.split(':');
        let entity = elems.next().expect("missing first element");
        let action = elems.next().expect("missing second element");
        use CoreCreditCollectionActionDiscriminants::*;
        let res = match entity.parse()? {
            Obligation => CoreCreditCollectionAction::from(action.parse::<ObligationAction>()?),
        };
        Ok(res)
    }
}

#[macro_export]
#[doc(hidden)]
macro_rules! __define_config_spec {
    // With default: implements DefaultedConfig
    (
        name: $name:ident,
        key: $key:literal,
        visibility: $visibility:path,
        visibility_marker: $marker:path,
        kind: $kind:ty,
        value_ty: $value_ty:ty,
        flavor: $flavor:ty,
        encrypted: $encrypted:expr,
        default: $default:expr;
        $(validate: $validate:expr;)?
    ) => {
        impl $crate::ConfigSpec for $name {
            const KEY: $crate::DomainConfigKey = $crate::DomainConfigKey::new($key);
            const VISIBILITY: $crate::Visibility = $visibility;
            type Kind = $kind;
            type Flavor = $flavor;

            fn default_value() -> Option<$value_ty> { ($default)() }
            $(fn validate(value: &$value_ty) -> Result<(), $crate::DomainConfigError> {
                ($validate)(value)
            })?
        }

        impl $marker for $name {}
        impl $crate::DefaultedConfig for $name {}

        $crate::inventory::submit! {
            $crate::registry::ConfigSpecEntry {
                key: $key,
                visibility: $visibility,
                config_type: <$kind as $crate::ValueKind>::TYPE,
                encrypted: $encrypted,
                validate_json: <$name as $crate::ConfigSpec>::validate_json,
                default_json: || <$name as $crate::ConfigSpec>::default_value()
                    .and_then(|v| <$kind as $crate::ValueKind>::encode(&v).ok())
                    .map($crate::DomainConfigValue::plain),
            }
        }
    };
    // Without default: does not implement DefaultedConfig
    (
        name: $name:ident,
        key: $key:literal,
        visibility: $visibility:path,
        visibility_marker: $marker:path,
        kind: $kind:ty,
        value_ty: $value_ty:ty,
        flavor: $flavor:ty,
        encrypted: $encrypted:expr,
        $(validate: $validate:expr;)?
    ) => {
        impl $crate::ConfigSpec for $name {
            const KEY: $crate::DomainConfigKey = $crate::DomainConfigKey::new($key);
            const VISIBILITY: $crate::Visibility = $visibility;
            type Kind = $kind;
            type Flavor = $flavor;

            $(fn validate(value: &$value_ty) -> Result<(), $crate::DomainConfigError> {
                ($validate)(value)
            })?
        }

        impl $marker for $name {}

        $crate::inventory::submit! {
            $crate::registry::ConfigSpecEntry {
                key: $key,
                visibility: $visibility,
                config_type: <$kind as $crate::ValueKind>::TYPE,
                encrypted: $encrypted,
                validate_json: <$name as $crate::ConfigSpec>::validate_json,
                default_json: || None,
            }
        }
    };
}

