        .await?;

    // overdraw
    let withdrawal_amount = UsdCents::try_from_usd(dec!(5000000)).unwrap();
    let withdrawal = deposit
        .initiate_withdrawal(&DummySubject, account.id, withdrawal_amount, None)
        .await;
    assert!(matches!(
        withdrawal,
        Err(core_deposit::error::CoreDepositError::DepositLedgerError(_))
    ));

    let withdrawal_amount = UsdCents::try_from_usd(dec!(500000)).unwrap();

    let withdrawal = deposit
        .initiate_withdrawal(&DummySubject, account.id, withdrawal_amount, None)
        .await?;

    let balance = deposit.account_balance(&DummySubject, account.id).await?;
    assert_eq!(balance.settled, deposit_amount - withdrawal_amount);
    assert_eq!(balance.pending, withdrawal_amount);

    deposit
        .cancel_withdrawal(&DummySubject, withdrawal.id)
        .await?;
    let balance = deposit.account_balance(&DummySubject, account.id).await?;
    assert_eq!(balance.settled, deposit_amount);

    Ok(())
}

// impl CoreAccounting
pub fn new(
        pool: &sqlx::PgPool,
        authz: &Perms,
        cala: &CalaLedger,
        journal_id: CalaJournalId,
        document_storage: DocumentStorage,
        jobs: &mut Jobs,
        outbox: &Outbox<E>,
    ) -> Self {
        let clock = jobs.clock().clone();
        let chart_of_accounts = ChartOfAccounts::new(pool, clock.clone(), authz, cala, journal_id);
        let fiscal_year = FiscalYears::new(pool, clock.clone(), authz, &chart_of_accounts);
        let journal = Journal::new(authz, cala, journal_id);
        let ledger_accounts = LedgerAccounts::new(authz, cala, journal_id);
        let manual_transactions = ManualTransactions::new(
            pool,
            authz,
            &chart_of_accounts,
            cala,
            journal_id,
            clock.clone(),
        );
        let ledger_transactions = LedgerTransactions::new(authz, cala);
        let profit_and_loss = ProfitAndLossStatements::new(pool, authz, cala, journal_id);
        let transaction_templates = TransactionTemplates::new(authz, cala);
        let balance_sheets = BalanceSheets::new(pool, authz, cala, journal_id);
        let csvs =
            AccountingCsvExports::new(authz, jobs, document_storage, &ledger_accounts, outbox);
        let trial_balances = TrialBalances::new(pool, authz, cala, journal_id);
        Self {
            clock,
            authz: authz.clone(),
            chart_of_accounts,
            journal,
            ledger_accounts,
            ledger_transactions,
            manual_transactions,
            profit_and_loss,
            transaction_templates,
            balance_sheets,
            csvs,
            trial_balances,
            fiscal_year,
        }
    }

