// impl GraphqlClient
pub async fn file_reports_runs(
        &self,
        limit: i32,
        cursor: Option<String>,
    ) -> Result<FileReportsRunsResponse, DagsterError> {
        let query = r#"
query FileReportsRuns($limit: Int!, $cursor: String, $pipelineName: String) {
  runsOrError(
    limit: $limit
    cursor: $cursor
    filter: {pipelineName: $pipelineName}
  ) {
    ... on Runs {
      count
      results {
        runId
        status
        startTime
        tags {
          key
          value
        }
      }
    }
  }
}
"#;

        let variables = if let Some(cursor) = cursor {
            json!({
                "limit": limit,
                "cursor": cursor,
                "pipelineName": &self.config.pipeline_name_for_report_generation
            })
        } else {
            json!({
                "limit": limit,
                "pipelineName": &self.config.pipeline_name_for_report_generation
            })
        };

        let request = json!({
            "query": query,
            "variables": variables
        });

        let response = self
            .http
            .post(self.config.uri.clone())
            .json(&request)
            .send()
            .await?;

        if !response.status().is_success() {
            return Err(DagsterError::ApiError);
        }

        let response_data: FileReportsRunsResponse = response.json().await?;
        Ok(response_data)
    }

