// impl CoreCredit
pub async fn init(
        pool: &sqlx::PgPool,
        governance: &Governance<Perms, E>,
        jobs: &mut Jobs,
        authz: &Perms,
        customer: &Customers<Perms, E>,
        custody: &CoreCustody<Perms, E>,
        price: &Price,
        outbox: &Outbox<E>,
        cala: &CalaLedger,
        journal_id: cala_ledger::JournalId,
        public_ids: &PublicIds,
        domain_configs: &ExposedDomainConfigsReadOnly,
        internal_domain_configs: &InternalDomainConfigs,
    ) -> Result<Self, CoreCreditError>
    where
        E: OutboxEventMarker<CoreTimeEvent>,
    {
        let clock = jobs.clock().clone();

        // Create Arc-wrapped versions of parameters once
        let authz_arc = Arc::new(authz.clone());
        let governance_arc = Arc::new(governance.clone());
        // let jobs_arc = Arc::new(jobs.clone());
        let price_arc = Arc::new(price.clone());
        let public_ids_arc = Arc::new(public_ids.clone());
        let customer_arc = Arc::new(customer.clone());
        let custody_arc = Arc::new(custody.clone());
        let cala_arc = Arc::new(cala.clone());
        let internal_domain_configs_arc = Arc::new(internal_domain_configs.clone());

        let publisher = CreditFacilityPublisher::new(outbox);
        let collections_publisher = core_credit_collection::CollectionPublisher::new(outbox);
        let ledger = CreditLedger::init(cala, journal_id, clock.clone()).await?;
        let ledger_arc = Arc::new(ledger);

        let collections = CoreCreditCollection::init(
            pool,
            authz_arc.clone(),
            cala,
            journal_id,
            ledger_arc.payments_made_omnibus_account_ids().account_id,
            jobs,
            &collections_publisher,
            outbox,
            clock.clone(),
        )
        .await?;
        let collections_arc = Arc::new(collections);

        let credit_facility_proposals = CreditFacilityProposals::init(
            pool,
            authz_arc.clone(),
            &publisher,
            governance_arc.clone(),
            clock.clone(),
        )
        .await?;
        let proposals_arc = Arc::new(credit_facility_proposals);

        let collaterals = Collaterals::init(
            pool,
            authz_arc.clone(),
            cala,
            journal_id,
            ledger_arc.collateral_omnibus_account_ids().account_id,
            ledger_arc.collateral_account_sets(),
            outbox,
            jobs,
            price_arc.clone(),
        )
        .await?;
        let collaterals_arc = Arc::new(collaterals);

        let pending_credit_facilities = PendingCreditFacilities::init(
            pool,
            proposals_arc.clone(),
            custody_arc.clone(),
            collaterals_arc.clone(),
            authz_arc.clone(),
            ledger_arc.clone(),
            price_arc.clone(),
            &publisher,
            governance_arc.clone(),
            jobs,
            outbox,
            clock.clone(),
        )
        .await?;
        let pending_credit_facilities_arc = Arc::new(pending_credit_facilities);

        let disbursals = Disbursals::init(
            pool,
            authz_arc.clone(),
            &publisher,
            collections_arc.clone(),
            governance_arc.clone(),
            clock.clone(),
        )
        .await?;
        let disbursals_arc = Arc::new(disbursals);

        let credit_facilities = CreditFacilities::init(
            pool,
            authz_arc.clone(),
            collections_arc.clone(),
            pending_credit_facilities_arc.clone(),
            disbursals_arc.clone(),
            ledger_arc.clone(),
            price_arc.clone(),
            jobs,
            &publisher,
            governance_arc.clone(),
            public_ids_arc.clone(),
            outbox,
            clock.clone(),
            collaterals_arc.clone(),
        )
        .await?;
        let facilities_arc = Arc::new(credit_facilities);

        let histories_arc = Arc::new(Histories::init(pool, outbox, jobs, authz_arc.clone()).await?);

        let repayment_plans_arc =
            Arc::new(RepaymentPlans::init(pool, outbox, jobs, authz_arc.clone()).await?);

        let chart_of_accounts_integrations = ChartOfAccountsIntegrations::new(
            authz_arc.clone(),
            ledger_arc.clone(),
            internal_domain_configs_arc.clone(),
        );
        let chart_of_accounts_integrations_arc = Arc::new(chart_of_accounts_integrations);

        // Register allocate payment handler + command job
        let allocate_payment_spawner =
            jobs.add_initializer(AllocatePaymentJobInitializer::new(collections_arc.clone()));

        outbox
            .register_event_handler(
                jobs,
                OutboxEventJobConfig::new(ALLOCATE_CREDIT_FACILITY_PAYMENT),
                AllocateCreditFacilityPaymentHandler::new(allocate_payment_spawner),
            )
            .await?;

        // Register approve disbursal handler + command job
        let approve_disbursal_spawner = jobs.add_initializer(ApproveDisbursalJobInitializer::new(
            disbursals_arc.clone(),
            facilities_arc.clone(),
            ledger_arc.clone(),
            clock.clone(),
        ));

        outbox
            .register_event_handler(
                jobs,
                OutboxEventJobConfig::new(DISBURSAL_APPROVE_JOB),
                DisbursalApprovalHandler::new(approve_disbursal_spawner),
            )
            .await?;

        // Register activate credit facility handler + command job
        let activate_cf_spawner = jobs.add_initializer(ActivateCreditFacilityJobInitializer::new(
            facilities_arc.clone(),
        ));

        outbox
            .register_event_handler(
                jobs,
                OutboxEventJobConfig::new(CREDIT_FACILITY_ACTIVATE),
                CreditFacilityActivationHandler::new(activate_cf_spawner),
            )
            .await?;

        // Register approve credit facility proposal handler + command job
        let approve_proposal_spawner = jobs.add_initializer(
            ApproveCreditFacilityProposalJobInitializer::new(pending_credit_facilities_arc.clone()),
        );

        outbox
            .register_event_handler(
                jobs,
                OutboxEventJobConfig::new(CREDIT_FACILITY_PROPOSAL_APPROVE_JOB),
                CreditFacilityProposalApprovalHandler::new(approve_proposal_spawner),
            )
            .await?;

        Ok(Self {
            clock,
            authz: authz_arc,
            customer: customer_arc,
            credit_facility_proposals: proposals_arc,
            pending_credit_facilities: pending_credit_facilities_arc,
            facilities: facilities_arc,
            collections: collections_arc,
            collaterals: collaterals_arc,
            custody: custody_arc,
            disbursals: disbursals_arc,
            histories: histories_arc,
            repayment_plans: repayment_plans_arc,
            governance: governance_arc,
            ledger: ledger_arc,
            price: price_arc,
            domain_configs: domain_configs.clone(),
            cala: cala_arc,
            chart_of_accounts_integrations: chart_of_accounts_integrations_arc,
            public_ids: public_ids_arc,
        })
    }

// impl CreditFacilityCollateralizationFromEventsHandler
pub(super) async fn update_collateralization_from_events(
        &self,
        credit_facility_id: impl Into<CreditFacilityId> + std::fmt::Display + Copy,
    ) -> Result<(), crate::credit_facility::error::CreditFacilityError> {
        let mut op = self.repo.begin_op().await?;
        // if the pending facility is not collateralized enough to be activated there will be no
        // credit facility to update the collateralization state for
        let Some(mut credit_facility) = self
            .repo
            .maybe_find_by_id_in_op(&mut op, credit_facility_id.into())
            .await?
        else {
            return Ok(());
        };

        self.authz
            .audit()
            .record_system_entry_in_op(
                &mut op,
                crate::primitives::COLLATERALIZATION_SYNC,
                CoreCreditObject::all_credit_facilities(),
                CoreCreditAction::CREDIT_FACILITY_UPDATE_COLLATERALIZATION_STATE,
            )
            .await?;

        tracing::Span::current().record("credit_facility_id", credit_facility.id.to_string());

        let collateral_account_id = self
            .collaterals
            .collateral_ledger_account_ids_in_op(&mut op, credit_facility.collateral_id)
            .await?
            .collateral_account_id;

        let balances = self
            .ledger
            .get_credit_facility_balance_in_op(
                &mut op,
                credit_facility.account_ids,
                collateral_account_id,
            )
            .await?;
        let price = self.price.usd_cents_per_btc().await;

        if credit_facility
            .update_collateralization(price, CVLPct::UPGRADE_BUFFER, balances)
            .did_execute()
        {
            self.repo
                .update_in_op(&mut op, &mut credit_facility)
                .await?;

            op.commit().await?;
        }
        Ok(())
    }

