impl<Perms, E> ApproveWithdrawal<Perms, E>
where
    Perms: PermissionCheck,
    <<Perms as PermissionCheck>::Audit as AuditSvc>::Action:
        From<CoreDepositAction> + From<GovernanceAction>,
    <<Perms as PermissionCheck>::Audit as AuditSvc>::Object:
        From<CoreDepositObject> + From<GovernanceObject>,
    E: OutboxEventMarker<GovernanceEvent> + OutboxEventMarker<CoreDepositEvent>,
{
    pub fn new(
        repo: &WithdrawalRepo<E>,
        audit: &Perms::Audit,
        governance: &Governance<Perms, E>,
        ledger: &DepositLedger,
    ) -> Self {
        Self {
            repo: repo.clone(),
            audit: audit.clone(),
            governance: governance.clone(),
            ledger: ledger.clone(),
        }
    }

    #[record_error_severity]
    #[instrument(name = "core_deposit.withdrawal_approval.execute", skip(self, op))]
    pub async fn execute_withdrawal_approval_in_op(
        &self,
        op: &mut es_entity::DbOp<'_>,
        id: WithdrawalId,
        approved: bool,
    ) -> Result<Withdrawal, WithdrawalError> {
        let mut withdraw = self.repo.find_by_id_in_op(&mut *op, id).await?;
        self.audit
            .record_system_entry_in_op(
                &mut *op,
                crate::primitives::DEPOSIT_APPROVAL,
                CoreDepositObject::withdrawal(id),
                CoreDepositAction::Withdrawal(WithdrawalAction::ConcludeApprovalProcess),
            )
            .await?;
        match withdraw.approval_process_concluded(approved) {
            es_entity::Idempotent::Executed(Some(denied_tx_id)) => {
                self.repo.update_in_op(&mut *op, &mut withdraw).await?;
                self.ledger
                    .deny_withdrawal_in_op(
                        &mut *op,
                        withdraw.id,
                        denied_tx_id,
                        withdraw.amount,
                        withdraw.deposit_account_id,
                        &<<Perms as PermissionCheck>::Audit as AuditSvc>::Subject::system(
                            crate::primitives::DEPOSIT_APPROVAL,
                        ),
                    )
                    .await?;
            }
            es_entity::Idempotent::Executed(None) => {
                self.repo.update_in_op(&mut *op, &mut withdraw).await?;
            }
            _ => (),
        };
        Ok(withdraw)
    }
}

impl ToTokens for OutboxEvent {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        let enum_ident = &self.ident;
        let crate_name: syn::Path = self.crate_name.parse().expect("invalid crate path");

        let variants = match &self.data {
            darling::ast::Data::Enum(variants) => variants,
            _ => panic!("OutboxEvent can only be derived for enums"),
        };

        for variant in variants {
            // Skip variants marked with #[serde(other)]
            if variant.other {
                continue;
            }

            // Only handle tuple variants with exactly one field
            let fields = match &variant.fields.style {
                darling::ast::Style::Tuple => &variant.fields.fields,
                _ => continue,
            };

            if fields.len() != 1 {
                continue;
            }

            let variant_ident = &variant.ident;
            let field_type = &fields[0];

            tokens.append_all(quote! {
                impl #crate_name::out::OutboxEventMarker<#field_type> for #enum_ident {
                    fn as_event(&self) -> Option<&#field_type> {
                        match self {
                            Self::#variant_ident(event) => Some(event),
                            _ => None,
                        }
                    }
                }

                impl From<#field_type> for #enum_ident {
                    fn from(event: #field_type) -> Self {
                        Self::#variant_ident(event)
                    }
                }
            });
        }
    }
}

