// impl CreditFacilities
pub async fn init(
        pool: &sqlx::PgPool,
        authz: Arc<Perms>,
        collections: Arc<CoreCreditCollection<Perms, E>>,
        pending_credit_facilities: Arc<PendingCreditFacilities<Perms, E>>,
        disbursals: Arc<Disbursals<Perms, E>>,
        ledger: Arc<CreditLedger>,
        price: Arc<Price>,
        jobs: &mut Jobs,
        publisher: &CreditFacilityPublisher<E>,
        governance: Arc<Governance<Perms, E>>,
        public_ids: Arc<PublicIds>,
        outbox: &Outbox<E>,
        clock: ClockHandle,
        collaterals: Arc<core_credit_collateral::Collaterals<Perms, E>>,
    ) -> Result<Self, CreditFacilityError>
    where
        E: OutboxEventMarker<core_time_events::CoreTimeEvent>,
    {
        let repo = Arc::new(CreditFacilityRepo::new(pool, publisher, clock.clone()));

        let update_collateralization_spawner = jobs.add_initializer(
            jobs::update_collateralization::UpdateCollateralizationJobInitializer::<Perms, E>::new(
                repo.clone(),
                collaterals.clone(),
                price.clone(),
                ledger.clone(),
                authz.clone(),
            ),
        );

        outbox
            .register_event_handler(
                jobs,
                OutboxEventJobConfig::new(
                    jobs::collateralization_from_events::CREDIT_FACILITY_COLLATERALIZATION_FROM_EVENTS_JOB,
                ),
                jobs::collateralization_from_events::CreditFacilityCollateralizationFromEventsHandler::<
                    Perms,
                    E,
                >::new(
                    update_collateralization_spawner,
                    repo.clone(),
                    collaterals.clone(),
                    ledger.clone(),
                    authz.clone(),
                ),
            )
            .await?;

        let maturity_spawner = jobs.add_initializer(
            jobs::credit_facility_maturity::CreditFacilityMaturityInit::new(repo.clone()),
        );

        let process_accrual_cycle_spawner =
            jobs.add_initializer(jobs::process_accrual_cycle::ProcessAccrualCycleJobInit::<
                Perms,
                E,
            >::new(
                ledger.clone(),
                collections.clone(),
                repo.clone(),
                collaterals.clone(),
                authz.clone(),
            ));

        let collect_facilities_for_accrual_spawner = jobs.add_initializer(
            jobs::collect_facilities_for_accrual::CollectFacilitiesForAccrualJobInit::new(
                repo.as_ref(),
                process_accrual_cycle_spawner,
            ),
        );

        let process_facility_maturities_spawner = jobs.add_initializer(
            jobs::process_facility_maturities::ProcessFacilityMaturitiesJobInit::new(
                repo.clone(),
                maturity_spawner.clone(),
            ),
        );

        outbox
            .register_event_handler(
                jobs,
                OutboxEventJobConfig::new(jobs::end_of_day::FACILITY_END_OF_DAY),
                jobs::end_of_day::FacilityEndOfDayHandler::new(
                    collect_facilities_for_accrual_spawner,
                    process_facility_maturities_spawner,
                ),
            )
            .await?;

        let record_liquidation_started_spawner = jobs.add_initializer(
            jobs::record_liquidation_started::RecordLiquidationStartedJobInitializer::new(
                collaterals.clone(),
                ledger.liquidation_proceeds_omnibus_account_ids().account_id,
            ),
        );

        let record_liquidation_proceeds_spawner = jobs.add_initializer(
            jobs::record_liquidation_proceeds::RecordLiquidationProceedsJobInitializer::new(
                collections.clone(),
                collaterals.clone(),
                repo.clone(),
            ),
        );

        outbox
            .register_event_handler(
                jobs,
                OutboxEventJobConfig::new(
                    jobs::credit_facility_liquidations::CREDIT_FACILITY_LIQUIDATIONS_JOB,
                ),
                jobs::credit_facility_liquidations::CreditFacilityLiquidationsHandler::new(
                    record_liquidation_started_spawner,
                    record_liquidation_proceeds_spawner,
                ),
            )
            .await?;

        Ok(Self {
            repo,
            collaterals,
            collections,
            pending_credit_facilities,
            disbursals,
            authz,
            ledger,
            price,
            governance,
            public_ids,
            clock,
        })
    }

