#[macro_export]
#[doc(hidden)]
macro_rules! __with_encrypted {
    // encrypted: true with default — not allowed
    (
        [$($prefix:tt)*]
        encrypted: true; default: $($rest:tt)*
    ) => {
        ::core::compile_error!("Encrypted domain configs cannot have a `default:` value");
    };
    // encrypted: true
    (
        [$($prefix:tt)*]
        encrypted: true; $($rest:tt)*
    ) => {
        $crate::__define_config_spec! {
            $($prefix)*
            flavor: $crate::DomainConfigFlavorEncrypted,
            encrypted: true,
            $($rest)*
        }
    };
    // encrypted: false
    (
        [$($prefix:tt)*]
        encrypted: false; $($rest:tt)*
    ) => {
        $crate::__define_config_spec! {
            $($prefix)*
            flavor: $crate::DomainConfigFlavorPlaintext,
            encrypted: false,
            $($rest)*
        }
    };
    // encrypted: absent — default to false/plaintext
    (
        [$($prefix:tt)*]
        $($rest:tt)*
    ) => {
        $crate::__define_config_spec! {
            $($prefix)*
            flavor: $crate::DomainConfigFlavorPlaintext,
            encrypted: false,
            $($rest)*
        }
    };
}

