#[macro_export]
macro_rules! define_exposed_config {
    // With default
    (
        $(#[$meta:meta])*
        $vis:vis struct $name:ident ($inner:ty);
        spec {
            key: $key:literal;
            $($spec_rest:tt)*
        }
    ) => {
        $(#[$meta])*
        $vis struct $name(pub $inner);

        $crate::__with_encrypted! {
            [
                name: $name,
                key: $key,
                visibility: $crate::Visibility::Exposed,
                visibility_marker: $crate::ExposedConfig,
                kind: $crate::Simple<$inner>,
                value_ty: $inner,
            ]
            $($spec_rest)*
        }
    };
}

#[instrument(name = "domain_config.seed_registered", skip_all)]
async fn seed_registered(repo: &DomainConfigRepo) -> Result<(), DomainConfigError> {
    let mut seen = HashSet::new();
    for spec in registry::all_specs() {
        if !seen.insert(spec.key) {
            return Err(DomainConfigError::InvalidKey(format!(
                "Duplicate domain config key: {}",
                spec.key
            )));
        }

        let key = DomainConfigKey::new(spec.key);
        if repo.maybe_find_by_key(key.clone()).await?.is_some() {
            continue;
        }

        let config_id = DomainConfigId::new();
        let new = NewDomainConfig::builder()
            .seed(
                config_id,
                key,
                spec.config_type,
                spec.visibility,
                spec.encrypted,
            )
            .default_value((spec.default_json)())
            .build()?;
        match repo.create(new).await {
            Ok(_) => {}
            Err(e) if e.was_duplicate() => continue,
            Err(err) => return Err(err.into()),
        }
    }

    Ok(())
}

